{
  "claims": [
    {
      "claim": "Pilot testing of a GAI-based chatbot achieved a retrieval rate of 41 out of 49, which is 83.7%.",
      "source_id": "6ad893b450b3ea15",
      "evidence_quote": "RESULTS: Pilot testing achieved a retrieval rate of 41/49 (83.7%).",
      "confidence": 0.9
    },
    {
      "claim": "In the main sample, the chatbot identified a median of 67.4% of included studies, with an inter-quartile range of 43.1%-88.4%.",
      "source_id": "6ad893b450b3ea15",
      "evidence_quote": "In the main sample (1169 studies; median 13.5 studies per SR), the chatbot identified a median of 67.4% of included studies (IQR: 43.1%-88.4%).",
      "confidence": 0.9
    },
    {
      "claim": "When limited to indexed studies, the retrieval rate for the GAI-based chatbot rose to 72.0% (IQR: 46.0%-92.5%).",
      "source_id": "6ad893b450b3ea15",
      "evidence_quote": "When limited to indexed studies (n = 1114), retrieval rose to 72.0% (IQR: 46.0%-92.5%).",
      "confidence": 0.9
    },
    {
      "claim": "A GAI-based chatbot can quickly generate SR searches, identifying approximately 67%-72% of studies, serving as a useful starting point but not a replacement for expert-led approaches.",
      "source_id": "6ad893b450b3ea15",
      "evidence_quote": "CONCLUSIONS: A GAI-based chatbot can rapidly generate SR searches (~67%-72% identification), serving as a useful starting point but not a replacement for expert-led approaches.",
      "confidence": 0.9
    },
    {
      "claim": "GPT-4 was systematically applied to summarize studies on pediatric long COVID published between January 2022 and January 2025 to evaluate the potential of more advanced models.",
      "source_id": "4afef193d051a3dc",
      "evidence_quote": "To evaluate the potential of more advanced models, we systematically applied GPT-4 to summarize studies on pediatric long COVID published between January 2022 and January 2025.",
      "confidence": 0.9
    },
    {
      "claim": "The exponential growth of COVID-19 literature makes comprehensive appraisal by individual researchers increasingly unfeasible, necessitating new approaches to evidence synthesis.",
      "source_id": "4afef193d051a3dc",
      "evidence_quote": "The exponential expansion of the COVID-19 literature has made comprehensive appraisal by individual researchers increasingly unfeasible, highlighting the need for new approaches to evidence synthesis.",
      "confidence": 0.9
    },
    {
      "claim": "Valsci is an open-source, self-hostable utility that automates large-batch scientific claim verification using any OpenAI-compatible large language model.",
      "source_id": "4ade729f26e7adcb",
      "evidence_quote": "In this paper, we introduce Valsci, an open-source, self-hostable utility that automates large-batch scientific claim verification using any OpenAI-compatible large language model.",
      "confidence": 0.9
    },
    {
      "claim": "Valsci grounds its analyses in verifiable published findings, unlike conventional standalone LLMs which often suffer from hallucinations and unreliable citations.",
      "source_id": "4ade729f26e7adcb",
      "evidence_quote": "Unlike conventional standalone LLMs, which often suffer from hallucinations and unreliable citations, Valsci grounds its analyses in verifiable published findings.",
      "confidence": 0.9
    }
  ]
}

